-- One-time: the turning code keys follow the turning catalog. The carbide
-- insert key gets every chipformer's description and the selection guide;
-- the toolholder key gets the clamping system codes (M pin and clamp vs M…W
-- top wedge lock, MU multi-wedge), X shape, round insert size and ISCAR's
-- prefixes and suffixes. Edits are kept: rows keep their picture (and their
-- details when the catalog has none), rows added by hand stay at the end.

-- A section's rows: the new rows in order, each with the old row's picture
-- (by its code, or "from"); then old rows not replaced (unless dropped).
CREATE FUNCTION "_ck_rows"(old jsonb, new jsonb, dropped text[]) RETURNS jsonb AS $f$
  SELECT COALESCE((
    SELECT jsonb_agg(r ORDER BY o, i) FROM (
      SELECT 0 AS o, i, (n - 'from') || COALESCE((
        SELECT jsonb_strip_nulls(jsonb_build_object('image', x -> 'image', 'details', CASE WHEN n ? 'details' THEN NULL ELSE x -> 'details' END))
        FROM jsonb_array_elements(COALESCE(old, '[]'::jsonb)) x
        WHERE x ->> 'code' = COALESCE(n ->> 'from', n ->> 'code') LIMIT 1
      ), '{}'::jsonb) AS r
      FROM jsonb_array_elements(new) WITH ORDINALITY AS t(n, i)
      UNION ALL
      SELECT 1, i, x FROM jsonb_array_elements(COALESCE(old, '[]'::jsonb)) WITH ORDINALITY AS t(x, i)
      WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(new) n WHERE n ->> 'code' = x ->> 'code' OR n ->> 'from' = x ->> 'code')
        AND NOT (x ->> 'code' = ANY(dropped))
    ) q
  ), '[]'::jsonb)
$f$ LANGUAGE sql;

-- Replaces a section (found by "key" or "title") with the patch, merging its
-- rows; appends the patch as a new section when there is none.
CREATE FUNCTION "_ck_section"(v jsonb, field text, match text, patch jsonb, dropped text[]) RETURNS jsonb AS $f$
  SELECT CASE WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(v -> 'sections') s WHERE s ->> field = match)
    THEN jsonb_set(v, '{sections}', (
      SELECT jsonb_agg(CASE WHEN s ->> field = match THEN s || (patch - 'rows') || jsonb_build_object('rows', "_ck_rows"(s -> 'rows', patch -> 'rows', dropped)) ELSE s END ORDER BY i)
      FROM jsonb_array_elements(v -> 'sections') WITH ORDINALITY AS t(s, i)))
    ELSE jsonb_set(v, '{sections}', (v -> 'sections') || jsonb_build_array((patch - 'rows') || jsonb_build_object('rows', "_ck_rows"('[]'::jsonb, patch -> 'rows', dropped))))
  END
$f$ LANGUAGE sql;

-- Adds rows at the end of a section (by "key"), unless their code is there.
CREATE FUNCTION "_ck_add_rows"(v jsonb, match text, add jsonb) RETURNS jsonb AS $f$
  SELECT jsonb_set(v, '{sections}', (
    SELECT jsonb_agg(CASE WHEN s ->> 'key' = match THEN jsonb_set(s, '{rows}', (s -> 'rows') || COALESCE((
      SELECT jsonb_agg(n) FROM jsonb_array_elements(add) n
      WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(s -> 'rows') x WHERE x ->> 'code' = n ->> 'code')), '[]'::jsonb)) ELSE s END ORDER BY i)
    FROM jsonb_array_elements(v -> 'sections') WITH ORDINALITY AS t(s, i)))
$f$ LANGUAGE sql;

UPDATE "AppSetting"
SET "value" = (
  "_ck_section"("value"::jsonb, 'title', '9 · Chipformer', $ck${"title": "9 · Chipformer", "sample": "GN", "rows": [{"code": "SF", "meaning": "Super finishing at very low feeds and depths of cut (negative)", "details": "Controls chip flow at very low feeds and cutting depths. Designed to reduce crater wear.\nSelection guide: P negative finishing, M negative finishing."}, {"code": "F3P", "meaning": "Finishing on steel – positive rake, low cutting forces", "details": "Negative inserts: double-sided, positive rake angle to reduce cutting forces for finish machining on steel.\nPositive inserts: super finishing and finishing. Feed 0.03–0.20 mm/rev, ap 0.25–3.0 mm.\nSelection guide: P negative finishing (first choice), P positive finishing (first choice)."}, {"code": "NF", "meaning": "Semi-finishing and finishing – very sharp edge, positive rake (negative)", "details": "Double-sided. Low cutting forces from a very sharp edge and positive rake.\nSelection guide: P negative finishing, M negative finishing, N negative finishing."}, {"code": "F3M", "meaning": "Finishing on stainless steel – positive rake", "details": "Negative inserts: double-sided; a deflector with a wavy surface prevents chip hammering.\nPositive inserts: also suitable for superalloys and exotic materials.\nSelection guide: M negative finishing (first choice), M positive finishing (first choice), S negative finishing, S positive finishing (first choice)."}, {"code": "F3S", "meaning": "Finishing on superalloys and exotic materials – positive rake (negative)", "details": "Chipbreaker with a positive rake angle.\nSelection guide: S negative finishing (first choice)."}, {"code": "F3N", "meaning": "Finishing on aluminum and non-ferrous – polished, extra sharp (negative)", "details": "Polished and extra sharp positive insert.\nSelection guide: N negative finishing (first choice)."}, {"code": "WF", "meaning": "Wiper for high-feed finishing on soft and gummy materials (negative)", "details": "Small depths of cut."}, {"code": "GN", "meaning": "General use – medium and semi-roughing on steel and cast iron (negative)", "details": "Double-sided with a secure cutting edge.\nSelection guide: P negative medium, P negative roughing, M negative roughing, K negative finishing, K negative medium."}, {"code": "TF", "meaning": "Medium – positive rake that prevents strain hardening (negative)", "details": "Double-sided. The rake angle varies along the edge to a negative angle, which prevents chipping; reduces cratering. For carbon and alloy steel and stainless steel.\nSelection guide: P negative medium, M negative medium, S negative medium."}, {"code": "M3P", "meaning": "Medium machining on steel – reinforced cutting edge", "details": "Negative inserts: double-sided, reinforced edge to increase tool life.\nPositive inserts: reinforced edge and positive rake angles.\nSelection guide: P negative medium (first choice), P positive medium (first choice), K negative finishing (first choice)."}, {"code": "M3M", "meaning": "Medium machining on stainless steel – reinforced cutting edge", "details": "Negative inserts: double-sided; the reinforced edge prevents notch wear at tight radii.\nPositive inserts: reinforced edge and positive rake angles.\nSelection guide: M negative medium (first choice), M positive medium (first choice), S negative medium (first choice), S positive medium (first choice)."}, {"code": "M3N", "meaning": "Medium machining on aluminum and non-ferrous – polished, extra sharp (negative)", "details": "Polished and extra sharp positive insert.\nSelection guide: N negative medium (first choice)."}, {"code": "M4PW", "meaning": "Roughing – feed 0.25–0.8 mm/rev, ap 2–10 mm (negative)", "details": "Double-sided.\nSelection guide: P negative medium."}, {"code": "M4MW", "meaning": "Heavy machining on stainless steel (negative)", "details": "Very positive radial helical cutting edge and a positive rake angle.\nSelection guide: M negative medium."}, {"code": "PP", "meaning": "Very positive, sharp – heat-resistant alloys, stainless, aluminum, soft steel (negative)", "details": "Double-sided, very positive rake with a sharp, positive radial edge. For heat-resistant alloys, stainless steel, aluminum alloys and soft, low carbon steel.\nSelection guide: P negative medium, M negative medium, N negative medium, S negative medium."}, {"code": "VL", "meaning": "High-temperature alloys – rough and finish turning (negative)", "details": "High positive rake and a special edge preparation. Excellent on parts such as automotive valves.\nSelection guide: M negative medium, S negative medium."}, {"code": "EM-M", "meaning": "High-temperature alloys at ap < 3 mm – 16° positive rake (negative)", "details": "Double-sided sharp cutting edge.\nSelection guide: S negative medium."}, {"code": "EM-R", "meaning": "High-temperature alloys at ap < 6 mm – 13° positive rake (negative)", "details": "Double-sided sharp cutting edge."}, {"code": "A", "meaning": "Flat insert (no chipformer) – short-chipping materials such as cast iron", "details": "Selection guide: K negative medium (first choice), K negative roughing (first choice)."}, {"code": "12", "meaning": "Medium to rough on aluminum and soft materials – single-sided (negative)"}, {"code": "R3P", "meaning": "Roughing on steel – positive rake, reinforced edge (negative)", "details": "Better performance and longer tool life.\nSelection guide: P negative roughing (first choice)."}, {"code": "R3M", "meaning": "Roughing on stainless steel – deflector for chip control (negative)", "details": "Double-sided; a wavy surface prevents chip hammering.\nSelection guide: M negative roughing (first choice)."}, {"code": "NR", "meaning": "Roughing – sharp edge, 13° positive rake (negative)", "details": "Double-sided. The catalog describes it for high temperature alloys at ap < 6 mm; the selection guide lists it for roughing steel, stainless steel and cast iron.\nSelection guide: P negative roughing, M negative roughing, K negative roughing."}, {"code": "T3P", "meaning": "High-feed turning on steel – trigon, 6° negative flank (negative)", "details": "Double-sided."}, {"code": "TNM", "meaning": "Roughing trigon – feed 0.25–0.65 mm/rev, ap 2–7 mm (negative)", "details": "Double-sided."}, {"code": "HT", "meaning": "Roughing – feed 0.25–0.8 mm/rev, ap 2–10 mm (negative)", "details": "Double-sided (HT/WG)."}, {"code": "WG", "meaning": "Roughing – feed 0.25–0.8 mm/rev, ap 2–10 mm (negative)", "details": "Double-sided (HT/WG)."}, {"code": "HM", "meaning": "Medium to rough – feed 0.08–0.75 mm/rev, ap 1.5–8 mm (negative)"}, {"code": "H3P", "meaning": "Heavy roughing – low cutting force for low-power machines (negative)", "details": "Excellent chip control thanks to a changeable land and a flexible chip breaker.\nSelection guide: P negative heavy."}, {"code": "H4P", "meaning": "Heavy roughing – large depth of cut and high feed (negative)", "details": "Strong cutting edge thanks to a wide land and a large land angle.\nSelection guide: P negative heavy (first choice)."}, {"code": "H5P", "meaning": "Heavy roughing – large depth of cut, high feed, extremely strong edge (negative)", "details": "Wide land and a large land angle; suitable for high cutting conditions.\nSelection guide: P negative heavy."}, {"code": "H6P", "meaning": "Tangential insert with 4 edges – high metal removal on steel, ap up to 35 mm"}, {"code": "PF", "meaning": "Super finishing and finishing – feed 0.03–0.20 mm/rev, ap 0.25–3 mm (positive)", "details": "Selection guide: P positive finishing, M positive finishing, S positive finishing."}, {"code": "SM", "meaning": "Finishing and boring – feed 0.06–0.25 mm/rev, ap 0.5–2.5 mm (positive)", "details": "Selection guide: P positive finishing, P positive medium, M positive finishing, M positive medium, K positive finishing (first choice), K positive medium (first choice), S positive finishing, S positive medium."}, {"code": "14", "meaning": "Semi-finishing and finishing, medium feeds (positive)", "details": "Selection guide: P positive finishing, M positive finishing, K positive finishing, K positive medium, S positive finishing."}, {"code": "AS", "meaning": "General machining of aluminum and soft materials (positive)", "details": "Selection guide: N positive finishing."}, {"code": "AF", "meaning": "Chipformer (listed in the catalog, no description there)"}, {"code": "NM", "meaning": "Chipformer (listed in the catalog, no description there)"}, {"code": "NMS", "meaning": "Roughing on aluminum (NMS12 in the selection guide)"}, {"code": "RP", "meaning": "Chipformer (listed in the catalog, no description there)"}, {"code": "RF", "meaning": "Right-hand version of a chipformer (../Z-RF)"}, {"code": "LF", "meaning": "Left-hand version of a chipformer (../Z-LF)"}], "note": "Selection guide by material and operation: see the table below. R / L in a chipformer name (e.g. ..-RF / LF): right-hand / left-hand insert."}$ck$::jsonb, ARRAY['AS/AF', '../Z-RF/LF'])
  || jsonb_build_object('tables', COALESCE(
    (SELECT jsonb_agg(t) FROM jsonb_array_elements("value"::jsonb -> 'tables') t WHERE t ->> 'title' NOT LIKE 'Chipformer selection guide%'), '[]'::jsonb)
    || jsonb_build_array($ck${"title": "Chipformer selection guide (★ = first choice; tight → open chip control)", "merge": 1, "columns": ["ISO group", "Insert", "Finishing", "Medium", "Roughing", "Heavy"], "rows": [["P – Steel", "Negative", "SF · F3P ★ · NF", "M4PW · TF · M3P ★ · GN · PP", "GN · R3P ★ · NR", "H3P · H4P ★ · H5P"], ["P – Steel", "Positive", "F3P ★ · PF · SM · 14", "SM · M3P ★", "", ""], ["M – Stainless steel", "Negative", "SF · F3M ★ · NF", "M4MW · TF · M3M ★ · VL · PP", "GN · R3M ★ · NR", ""], ["M – Stainless steel", "Positive", "SM · PF · F3M ★ · 14", "M3M ★ · SM", "", ""], ["K – Cast iron", "Negative", "M3P ★ · GN", "GN · A ★", "NR · A ★", ""], ["K – Cast iron", "Positive", "SM ★ · 14", "SM ★ · 14", "", ""], ["N – Aluminum", "Negative", "NF · F3N ★", "PP · M3N ★", "NMS12", ""], ["N – Aluminum", "Positive", "AS", "", "", ""], ["S – High temperature alloys", "Negative", "F3M · F3S ★", "TF · M3M ★ · EM-M · VL · PP", "", ""], ["S – High temperature alloys", "Positive", "SM · PF · F3M ★ · 14", "M3M ★ · SM", "", ""]]}$ck$::jsonb))
)::text
WHERE "key" = 'codekey.carbide';

UPDATE "AppSetting"
SET "value" = "_ck_section"("_ck_section"("_ck_section"("_ck_add_rows"("value"::jsonb, 'p5', $ck$[{"code": "X", "meaning": "Special shape (e.g. DXJNR: 70° rhombic)"}]$ck$::jsonb),
  'key', 'p4', $ck${"title": "4 · Clamping system", "rows": [{"code": "C", "meaning": "Top clamp (Iscadex)"}, {"code": "P", "meaning": "Lever lock"}, {"code": "S", "meaning": "Screw clamping (SC)"}, {"code": "M", "meaning": "Pin and clamp", "from": "-"}, {"code": "M…W", "meaning": "Top wedge lock (M with W / MW at position 12)", "from": "M"}, {"code": "MU", "meaning": "MULTI-WEDGE lock (MU…-MW; no insert shape letter)"}, {"code": "D", "meaning": "Rigid clamp (R-Clamp)"}], "note": "M: a top wedge lock when position 12 is W or MW (e.g. MWLNR 2525M-08W), otherwise pin and clamp (e.g. MCLNR 2525M-16)."}$ck$::jsonb, ARRAY[]::text[]),
  'key', 'p11', $ck${"title": "11 · Insert size", "rows": [{"code": "##", "meaning": "Cutting edge length in mm (e.g. 08 = 8 mm); for round inserts (R) the diameter"}]}$ck$::jsonb, ARRAY[]::text[]),
  'key', 'px', $ck${"key": "px", "title": "Prefixes & suffixes", "sample": "JHP", "rows": [{"code": "C#", "meaning": "CAMFIX polygon shank (C3 = 32, C4 = 40, C5 = 50, C6 = 63, C8 = 80 mm)"}, {"code": "#####", "meaning": "CAMFIX tool size code (e.g. 35060 – see the tool table)"}, {"code": "HSK", "meaning": "HSK taper shank (e.g. HSK A63WH)"}, {"code": "NQCH", "meaning": "JETCUT modular head for Swiss-type machines (e.g. NQCH16)"}, {"code": "AVC", "meaning": "Interchangeable head for anti-vibration (AV) bars"}, {"code": "D##", "meaning": "Head diameter in mm (AVC-D25 = 25 mm)"}, {"code": "Q#", "meaning": "For Q3 / Q6 Safety Lock high-feed inserts (Q3-MCMT, Q6-MNMG)"}, {"code": "Y", "meaning": "Y-axis turning tool"}, {"code": "H###", "meaning": "Dimension H in mm (e.g. H065 = 65 mm)"}, {"code": "JHP", "meaning": "Channels for high-pressure coolant"}, {"code": "MC", "meaning": "Bottom inlets for the high-pressure coolant channels (with JHP)"}, {"code": "X", "meaning": "For HELITURN LD X-type inserts (WNMX / CNMX / TNMX, also ..MG)"}, {"code": "SL", "meaning": "Safety Lock clamping"}, {"code": "IQ", "meaning": "Lever lock and dovetail pocket rigid clamping, for double-sided inserts"}, {"code": "PAD", "meaning": "Lever lock adapter with high-pressure coolant"}, {"code": "F", "meaning": "Screw lock with a wedge for high rigidity (profiling)"}, {"code": "FS", "meaning": "Screw lock with a wedge for high rigidity (profiling)"}, {"code": "TF", "meaning": "Fast feed longitudinal turning"}, {"code": "TANG", "meaning": "Tangentially clamped LNMX inserts"}, {"code": "CM", "meaning": "Takes four different 7° clearance geometries"}], "note": "From the families in the turning catalog, e.g. C5 PWLNR-35060-08X-JHP, HSK A63WH-MULNR-J12MWX2, AVC-D25-SDJCN-13-SL-Y. W / MW / S after the insert size: see position 12."}$ck$::jsonb, ARRAY[]::text[])::text
WHERE "key" IN (SELECT 'codekey.app.' || a."id" FROM "Application" a WHERE lower(a."name") = 'turning');

DROP FUNCTION "_ck_add_rows"(jsonb, text, jsonb);
DROP FUNCTION "_ck_section"(jsonb, text, text, jsonb, text[]);
DROP FUNCTION "_ck_rows"(jsonb, jsonb, text[]);
